import {prepareStyledSurface} from './styled-surface.js';
import {installCardFeel} from './card-feedback.js';
import {floorRewards,maxHealth,maxRhythm,power,campNeeded,SEALS,chooseAbyssCard} from './core.js';
import {abyssCardDefinition} from './abyss-cards.js';
import {CARDS,cardCount,cardDetail} from './cards.js';
import {depthLimit,TOTAL_FLOORS} from './campaign.js';
import {chosenCardView} from './chosen-card-view.js';
import {APPROVED_CARD_RASTERS} from './approved-card-raster.js';
import {HUD_ART} from './hud-art-registry.js';
import {POST_ACTION_ICONS} from './post-choice-data.js';
import {RECORDS} from './records.js';
import {serviceShadow} from './approved-service-host.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Math.round(n).toLocaleString('pt-BR');
const img=(src,cls='',alt='')=>'<img class="'+cls+'" src="'+src+'" alt="'+esc(alt)+'">';
const value=(src,n,label,plus=false)=>'<span class="value" aria-label="'+esc(label)+': '+fmt(n)+'">'+(src?img(src):'')+'<b>'+(plus?'+':'')+fmt(n)+'</b>'+(!src?'<small>pts</small>':'')+'</span>';
export function completionCardsView(profile){
 const r=profile?.run;if(!r?.room.cleared||r.mode==='abyss')return null;
 const q=floorRewards(profile),observed=chosenCardView(profile),c=observed.status==='chosen'?CARDS.find(c=>c.id===observed.id):null,canDescend=r.floor<depthLimit(profile)&&r.floor<TOTAL_FLOORS;
 return {floor:r.floor,depth:r.floor*25,health:Math.ceil(r.health),maxHealth:maxHealth(profile),reward:q,materialGains:r.materials.map((v,i)=>Math.max(0,v-(r.room.floorStart?.materials?.[i]||0))),bag:r.bag,crystals:r.materials.reduce((a,b)=>a+b,0),confirmed:!!r.cardChosen,canDescend,final:r.floor===TOTAL_FLOORS,camp:campNeeded(profile),sealName:SEALS[profile.seals]?.name||'',disc:RECORDS.find(d=>d.id===r.room.recordDrop)||null,card:c?{...c,level:cardCount(r,c.id),effect:cardDetail(c,cardCount(r,c.id),power(profile),0,profile)}:null};
}
export function approvedFloorOffersMarkup(offers){return offers.map(c=>'<button type="button" class="offer" data-card="'+esc(c.id)+'" aria-pressed="false"><span class="offer-meta"><span>'+esc(c.role)+'</span><span class="offer-level">'+(c.level?'Nv. '+c.level+' → '+(c.level+1):'Nova')+'</span></span>'+img(APPROVED_CARD_RASTERS[c.id],'card-art')+'<strong class="offer-name">'+esc(c.name)+'</strong><span class="offer-copy">'+esc(c.text)+'</span><span class="offer-effect">'+esc(c.detail)+'</span></button>').join('');}
export function immediateCardDetail(profile,id){
 if(!id.startsWith('abyss-'))return '';const after=structuredClone(profile);if(!chooseAbyssCard(after,id))return '';
 const r=profile.run,n=after.run;if(id==='abyss-heal')return 'Vida '+Math.ceil(r.health)+' → '+Math.ceil(n.health);
 if(id==='abyss-breath')return 'Fôlego '+Math.ceil(r.rhythm)+' → '+Math.ceil(n.rhythm);
 return 'Proteção por '+Math.max(0,n.guardUntil-Math.max(r.beat,r.acted))+' pulsos';
}
export function approvedAbyssOffersMarkup(offers,profile){return offers.map((c,i)=>'<button type="button" class="offer" data-abyss-card="'+esc(c.id)+'"><span class="meta"><kbd>'+(i+1)+'</kbd><span class="role">'+esc(c.role)+'</span><span class="level">'+(c.instant?'Imediato':c.level?'Nv. '+c.level+' → '+(c.level+1):'Nova')+'</span></span>'+img(APPROVED_CARD_RASTERS[c.id],'art')+'<strong class="name">'+esc(c.name)+'</strong><span class="copy">'+esc(c.text)+'</span><span class="effect">'+esc(c.instant?immediateCardDetail(profile,c.id):c.detail)+'</span></button>').join('');}
function installShell(doc){if(doc.querySelector('link[data-approved-expedition-cards-shell]'))return;const l=doc.createElement('link');l.rel='stylesheet';l.href='approved-expedition-cards-shell.css';l.dataset.approvedExpeditionCardsShell='';doc.head.append(l);}
if(typeof document!=='undefined')installShell(document);
const floorMarkup='<div id="gv-expedition-cards-v2"><div class="window"><header class="head">'+img('assets/crystal-veins-v5/vein-0.svg','emblem')+'<div><h2 id="clearTitle"></h2><p class="depth" id="choiceDepth"></p></div><div class="health" aria-label="Vida mantida">'+img(HUD_ART.heart.url,'','Vida')+'<b id="choiceHealth"></b><span id="choiceMaxHealth"></span></div></header><section class="loot" id="floorLoot" aria-label="Ganhos do andar"></section><section class="workspace"><h3 class="section-title" id="choiceStep">Escolha uma carta</h3><div class="offers" id="cardOffers"></div><div class="chosen" id="chosenCard" hidden></div></section><footer class="footer"><span class="guard" id="choiceGuard"></span><button type="button" class="button primary" id="confirmCard" disabled>Escolher</button><div class="actions" id="floorActions" hidden><button type="button" class="button" id="floorRescue">Resgatar carga</button><button type="button" class="button" id="safeReturn">'+img(POST_ACTION_ICONS.safeReturn)+'Voltar à base</button><button type="button" class="button primary" id="descend">'+img(POST_ACTION_ICONS.descend)+'Descer</button></div></footer><span id="clearSubtitle" hidden></span></div></div>';
const abyssMarkup='<div id="gv-expedition-abyss-v1"><section class="window" id="abyssChoiceWindow"><header class="head"><div><p class="badge" id="choiceAbyssSection"></p><h2 id="abyssCardTitle">Escolha seu poder</h2></div><div class="seconds"><b id="abyssCardSeconds">4</b><small> s</small></div></header><div class="timer" id="abyssCardTimer" role="progressbar" aria-label="Tempo restante para escolher" aria-valuemin="0" aria-valuemax="4"><i id="abyssCardFill"></i></div><div class="offers" id="abyssCardOffers"></div><p class="hint" id="abyssCardHint"></p></section></div>';
export function mountApprovedExpeditionCards(doc,{softMode=()=>false,onCommand=()=>{}}={}){
 installShell(doc);const fields=new Map(),shadows=[],animations=new Set();let pendingFocus=false,lastConfirmed=false,chosenKey='',lootKey='',notice=null,noticeTimer=null;
 function clearNotice(){clearTimeout(noticeTimer);notice?.remove();notice=null;}
 function bind(root){for(const e of root.querySelectorAll('[id]'))fields.set(e.id,e);}
 function surface(container,markup){const host=doc.createElement('div');host.className='approved-service-host';const shadow=host.attachShadow({mode:'open'});prepareStyledSurface(host,shadow);for(const href of ['approved-services.css','approved-expedition-cards-ui.css']){const l=doc.createElement('link');l.rel='stylesheet';l.href=href;shadow.append(l);}const t=doc.createElement('template');t.innerHTML=markup;shadow.append(t.content);container.replaceChildren(host);container.dataset.approvedExpeditionCards='';container.removeAttribute('aria-labelledby');bind(shadow);shadows.push(shadow);shadow.addEventListener('click',e=>{const b=e.composedPath().find(n=>n?.tagName==='BUTTON');if(!b||b.disabled)return;if(!['confirmCard','descend'].includes(b.id))onCommand();if(b.dataset.card&&!doc.documentElement.hasAttribute('data-card-vfx-enhanced'))setTimeout(()=>{if(!b.isConnected||b.getAttribute('aria-pressed')!=='true'||softMode()||doc.defaultView.matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(const a of animations)a.cancel();const art=b.querySelector('img');if(!art)return;const a=art.animate([{transform:'translateY(0)'},{transform:'translateY(-5px)',offset:.4},{transform:'translateY(0)'}],{duration:210,easing:'ease-out'});animations.add(a);a.finished.catch(()=>{}).finally(()=>animations.delete(a));},0);},true);return shadow;}
 const clear=doc.getElementById('clearBanner'),dialog=doc.getElementById('abyssCardDialog'),floor=surface(clear,floorMarkup),abyss=surface(dialog,abyssMarkup);clear.setAttribute('aria-label','Conclusão do andar e escolha de carta');dialog.setAttribute('aria-label','Escolha seu poder do Abismo');
 const field=id=>{const e=fields.get(id);return e?.isConnected?e:null;};
 const cardFeel=installCardFeel(doc,{soft:softMode,field,notice:()=>notice?.shadowRoot?.querySelector('.toast')});
 const facts=v=>'<div class="facts"><div><span>Mochila</span><br>'+value(HUD_ART.coin.url,v.bag,'Moedas na mochila')+'</div><div><span>Cristais</span><br><strong>'+fmt(v.crystals)+'</strong></div>'+(v.canDescend?'<div><span>Próximo andar</span><br><strong>'+(v.floor+1)+'</strong></div>':'')+'</div>';
 function renderLoot(profile){const v=completionCardsView(profile);if(!v)return;const signature=JSON.stringify([v.reward,v.materialGains,v.bag,v.disc?.id]);if(signature===lootKey)return;lootKey=signature;field('floorLoot').innerHTML='<span class="loot-title">'+(v.reward?'Neste andar':'Mochila atual')+'</span><div class="reward-items">'+(v.reward?value(HUD_ART.coin.url,v.reward.gems,'Moedas do andar',true)+value(HUD_ART.star.url,v.reward.stars,'Estrelas do andar',true)+value('',v.reward.points,'Pontos do andar',true):value(HUD_ART.coin.url,v.bag,'Moedas na mochila'))+'</div><div class="materials">'+v.materialGains.map((n,i)=>n>0?value('assets/refuge-night-v3/gem-'+i+'.png',n,'Fragmentos '+i,true):'').join('')+'</div>'+(v.disc?'<div class="disc">'+img('assets/approved-vitrola-v1/'+v.disc.id+'.webp')+esc(v.disc.name)+'</div>':'');}
 function refresh(profile){const v=completionCardsView(profile),r=profile?.run;for(const shadow of shadows)shadow.querySelector('[id^="gv-expedition-"]')?.setAttribute('data-soft',String(softMode()));
  if(r?.abyss?.cardChoice)clearNotice();field('choiceAbyssSection').textContent='Abismo · Trecho '+(r?.abyss?.cardChoice?.section||r?.abyss?.section||1);field('abyssChoiceWindow').dataset.urgent=dialog.dataset.urgent||'false';if(!v){lastConfirmed=false;chosenKey='';lootKey='';return;}
  field('clearTitle').textContent=v.final&&v.confirmed?'Bioma conquistado!':'Andar '+v.floor+' concluído';field('choiceDepth').textContent=fmt(v.depth)+' m';field('choiceHealth').textContent=v.health;field('choiceMaxHealth').textContent='/ '+v.maxHealth;field('choiceStep').textContent=v.confirmed?'Carta equipada':'Escolha uma carta';field('safeReturn').classList.toggle('primary',!v.canDescend);renderLoot(profile);
  if(v.confirmed){if(!lastConfirmed)pendingFocus=true;const key=JSON.stringify(v);if(key!==chosenKey){chosenKey=key;const c=v.card;field('chosenCard').classList.toggle('missing',!c);field('chosenCard').innerHTML=c?img(APPROVED_CARD_RASTERS[c.id],'',c.name)+'<div><span class="chosen-level">✓ Nv. '+c.level+'</span><h3 class="chosen-name">'+esc(c.name)+'</h3><p class="chosen-copy">'+esc(c.text)+'</p><div class="chosen-effect">'+esc(c.effect)+'</div>'+facts(v)+(v.final?'<p class="route-note">Volte à base com suas conquistas.</p>':!v.canDescend?'<p class="route-note">Próximo bioma: construa o '+esc(v.sealName.toLocaleLowerCase('pt-BR'))+'.</p>':v.camp?'<p class="route-note">Fogueira antes do próximo andar.</p>':'')+'</div>':'<div><h3 class="chosen-name">Carta escolhida</h3><p class="chosen-copy">Detalhes indisponíveis</p>'+facts(v)+'</div>';}}
  else{chosenKey='';pendingFocus=false;}lastConfirmed=v.confirmed;
 }
 function focusReady(){if(!pendingFocus||!doc.hasFocus()||clear.hidden||doc.getElementById('dialog').open)return;const b=[field('descend'),field('safeReturn')].find(b=>b&&!b.hidden&&!b.disabled);if(b){pendingFocus=false;b.focus({preventScroll:true});}}
 function mountSafeReturn(dialog,profile){const r=profile.run;const markup='<div id="gv-expedition-cards-v2"><section class="return-box"><h3>Voltar à base?</h3><div class="return-rewards">'+value(HUD_ART.coin.url,r.bag,'Moedas salvas')+'<span class="value"><b>'+fmt(r.materials.reduce((a,b)=>a+b,0))+'</b><small>cristais</small></span></div><div class="return-actions"><button type="button" class="button" id="stayInMine">Continuar na mina</button><button type="button" class="button primary" id="confirmSafeReturn" disabled>Salvar e voltar</button></div></section></div>';const shadow=serviceShadow(dialog,markup),l=doc.createElement('link');l.rel='stylesheet';l.href='approved-expedition-cards-ui.css';shadow.prepend(l);bind(shadow);dialog.dataset.approvedExpeditionSafeReturn='';return()=>{delete dialog.dataset.approvedExpeditionSafeReturn;};}
 function announceAbyss(profile,id,automatic){clearNotice();const c=abyssCardDefinition(id);if(!c||!profile.run)return;notice=doc.createElement('div');notice.className='approved-service-host';notice.style.cssText='position:fixed;inset:0;pointer-events:none;z-index:30';const shadow=notice.attachShadow({mode:'open'});prepareStyledSurface(notice,shadow);for(const href of ['approved-services.css','approved-expedition-cards-ui.css']){const l=doc.createElement('link');l.rel='stylesheet';l.href=href;shadow.append(l);}const t=doc.createElement('template');t.innerHTML='<div id="gv-expedition-abyss-v1" style="height:100%;position:relative"><div class="toast" role="status">'+img(APPROVED_CARD_RASTERS[id])+'<div><small>'+(automatic?'Sorteado':'Poder')+'</small><strong>'+esc(c.name)+'</strong><small>'+(id.startsWith('abyss-')?'Efeito imediato':'Nv. '+cardCount(profile.run,id))+'</small></div></div></div>';shadow.append(t.content);doc.body.append(notice);if(!softMode()&&!doc.defaultView.matchMedia('(prefers-reduced-motion: reduce)').matches)shadow.querySelector('.toast').animate([{opacity:0,transform:'translate(-50%,8px)'},{opacity:1,transform:'translate(-50%,0)'}],{duration:180,easing:'ease-out'});noticeTimer=setTimeout(clearNotice,1400);}
 const onHidden=()=>{if(doc.hidden)clearNotice();};doc.addEventListener('visibilitychange',onHidden);
 return{field,cardFeel,refresh,renderLoot,announceAbyss,mountSafeReturn,abyssReady:()=>!['loading','error'].includes(abyss.host.dataset.uiSurfaceState),floorOffers:approvedFloorOffersMarkup,abyssOffers:approvedAbyssOffersMarkup,focusReady,floorButtons:()=>[...floor.querySelectorAll('button')],floorActive:()=>floor.activeElement||doc.activeElement,dispose(){clearNotice();cardFeel.dispose();doc.removeEventListener('visibilitychange',onHidden);for(const a of animations)a.cancel();}};
}
